import {supabase,currentUser,accountUrl} from './auth-client.mjs';
const style=document.createElement('link');style.rel='stylesheet';style.href=new URL('./account-actions.css?v=1',import.meta.url);document.head.append(style);
const button=document.getElementById('delete-account');
const dialog=document.createElement('dialog');dialog.className='account-delete-dialog';dialog.setAttribute('aria-labelledby','delete-account-title');
dialog.innerHTML=`<h2 id="delete-account-title">Delete your account?</h2><p>This permanently deletes your website profile, album, trade preferences, chats, requests, saved formations and tierlists. Your UID will be released.</p><p>Your Discord account and game account will remain. Published site guides remain with anonymous history.</p><form><label for="delete-confirmation">Type DELETE to confirm</label><input id="delete-confirmation" autocomplete="off" spellcheck="false"><p role="status"></p><div class="delete-actions"><button type="button" data-cancel>Cancel</button><button type="submit" disabled>Permanently delete account</button></div></form>`;
document.body.append(dialog);let expected=null,busy=false;const form=dialog.querySelector('form'),input=dialog.querySelector('input'),submit=form.querySelector('[type=submit]'),status=dialog.querySelector('[role=status]');
document.getElementById('switch-account')?.addEventListener('click',async()=>{const {error}=await supabase.auth.signOut({scope:'local'});if(error){document.getElementById('account-status').textContent=error.message;return;}location.assign(accountUrl);});
export async function openAccountDeletion(){expected=(await currentUser())?.id;if(!expected)return;input.value='';status.textContent='';submit.disabled=true;dialog.showModal();dialog.querySelector('[data-cancel]').focus();}
button?.addEventListener('click',openAccountDeletion);
input.oninput=()=>submit.disabled=busy||input.value!=='DELETE';
dialog.querySelector('[data-cancel]').onclick=()=>{if(!busy)dialog.close();};dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault();});
form.onsubmit=async e=>{e.preventDefault();if(busy||input.value!=='DELETE')return;busy=true;submit.disabled=true;const deletingActor=expected;try{if((await currentUser())?.id!==deletingActor)throw Error('Your account changed. Close this dialog and try again.');const {error}=await supabase.rpc('delete_own_account',{p_expected_actor:deletingActor,p_confirmation:input.value});if(error)throw error;if((await currentUser())?.id===deletingActor)await supabase.auth.signOut({scope:'local'});location.replace(accountUrl);}catch(error){status.textContent=error.message;}finally{busy=false;submit.disabled=input.value!=='DELETE';}};
supabase.auth.onAuthStateChange((_event,session)=>{if(expected&&session?.user?.id!==expected){expected=null;input.value='';dialog.close();}});
